import * as THREE from './vendor/three.module.js';
import {SENSES,GATES} from './game.js';
export const PATH=[];
let left=-2,right=2,top=2,bottom=-2;
while(left<=right&&bottom<=top){for(let x=left;x<=right;x++)PATH.push([x,top]);top--;for(let z=top;z>=bottom;z--)PATH.push([right,z]);right--;if(bottom<=top){for(let x=right;x>=left;x--)PATH.push([x,bottom]);bottom++;}if(left<=right){for(let z=bottom;z<=top;z++)PATH.push([left,z]);left++;}}
const STEP=1.16;
export const pointAt=i=>new THREE.Vector3(PATH[i][0]*STEP,.35,PATH[i][1]*STEP);
export function roundedBox(w,h,d,r=.12){const shape=new THREE.Shape(),x=-w/2,y=-d/2;shape.moveTo(x+r,y);shape.lineTo(x+w-r,y);shape.quadraticCurveTo(x+w,y,x+w,y+r);shape.lineTo(x+w,y+d-r);shape.quadraticCurveTo(x+w,y+d,x+w-r,y+d);shape.lineTo(x+r,y+d);shape.quadraticCurveTo(x,y+d,x,y+d-r);shape.lineTo(x,y+r);shape.quadraticCurveTo(x,y,x+r,y);const g=new THREE.ExtrudeGeometry(shape,{depth:h,bevelEnabled:false,steps:1,curveSegments:6});g.rotateX(-Math.PI/2);g.translate(0,0,0);return g;}
function mat(color,roughness=.8,metalness=.05){return new THREE.MeshStandardMaterial({color,roughness,metalness});}
function mesh(geo,material,parent,x=0,y=0,z=0){const m=new THREE.Mesh(geo,material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
export function labelTexture(text,sub,color='#d5dee5',size=256){const canvas=document.createElement('canvas');canvas.width=canvas.height=size;const c=canvas.getContext('2d');c.clearRect(0,0,size,size);c.fillStyle=color;c.textAlign='center';c.textBaseline='middle';c.font=`600 ${sub?70:100}px Segoe UI, Arial`;c.fillText(text,size/2,sub?105:128);if(sub){c.font='500 23px Segoe UI, Arial';c.fillText(sub,size/2,180);}const t=new THREE.CanvasTexture(canvas);t.colorSpace=THREE.SRGBColorSpace;return t;}
function label(parent,text,sub,color,x,y,z,w=.75){const m=new THREE.Mesh(new THREE.PlaneGeometry(w,w),new THREE.MeshBasicMaterial({map:labelTexture(text,sub,color),transparent:true,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.set(x,y,z);parent.add(m);return m;}
function geometricNumber(parent,value,color,x,y,z){const segments={0:'abcedf',1:'bc',2:'abged',3:'abgcd',4:'fgbc',5:'afgcd',6:'afgecd',7:'abc',8:'abcdefg',9:'abfgcd'};const positions={a:[0,-.16,.12,.022],b:[.075,-.08,.022,.14],c:[.075,.08,.022,.14],d:[0,.16,.12,.022],e:[-.075,.08,.022,.14],f:[-.075,-.08,.022,.14],g:[0,0,.12,.022]};const str=String(value),material=mat(color);[...str].forEach((digit,j)=>{for(const s of segments[digit]){const [sx,sz,w,d]=positions[s];mesh(new THREE.BoxGeometry(w,.004,d),material,parent,x+sx+(j-(str.length-1)/2)*.23,y,z+sz);}});}
function clayGeometry(radius=1){const g=new THREE.SphereGeometry(radius,32,24);const a=g.attributes.position;for(let i=0;i<a.count;i++){let x=a.getX(i),y=a.getY(i),z=a.getZ(i);const n=1+.014*Math.sin(x*19+y*15)*Math.cos(z*21-y*9)+.006*Math.sin(y*37+x*13);a.setXYZ(i,x*n,y*n,z*n);}g.computeVertexNormals();return g;}
export function makeCharacter(color,scale=1,guardian=false){const group=new THREE.Group();group.name=guardian?'Moss — core guardian':color==='#79b9ce'?'Blu — clay explorer':'Ember — clay explorer';const bodyMat=mat(color,.97,0),cream=mat('#f5e9ce',.8,0),pupil=mat('#202c32',.35,0);const body=mesh(clayGeometry(),bodyMat,group,0,.39,0);body.scale.set(.31,.4,.25);const head=mesh(clayGeometry(),bodyMat,group,0,.68,-.005);head.scale.set(.32,.28,.25);for(const s of [-1,1]){const ear=mesh(new THREE.ConeGeometry(.12,.29,14),bodyMat,group,s*.24,.92,-.05);ear.rotation.z=s*-.32;const foot=mesh(clayGeometry(),bodyMat,group,s*.2,.1,.09);foot.scale.set(.17,.12,.22);const eye=mesh(clayGeometry(),cream,group,s*.145,.73,.215);eye.scale.set(.125,.137,.07);const iris=mesh(new THREE.SphereGeometry(.066,18,12),pupil,group,s*.145+.012,.735,.279);iris.scale.z=.36;const glint=mesh(new THREE.SphereGeometry(.019,10,8),mat('#ffffff',.1),group,s*.145-.005,.76,.3);glint.scale.z=.3;}
const smile=mesh(new THREE.TorusGeometry(.08,.009,6,18,Math.PI*.8),pupil,group,0,.53,.251);smile.rotation.z=Math.PI*1.1;group.scale.setScalar(scale);group.userData.character=true;return group;}
function icon(parent,sense,color,x,y,z){const material=new THREE.LineBasicMaterial({color});const points=[];if(sense===0){for(let i=0;i<=40;i++){const t=i/40*Math.PI*2;points.push(new THREE.Vector3(Math.cos(t)*.23,0,Math.sin(t)*.12));}const eye=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),material);eye.position.set(x,y,z);parent.add(eye);const pupil=mesh(new THREE.CylinderGeometry(.065,.065,.008,18),mat(color),parent,x,y+.002,z);return;}if(sense===1){for(let i=0;i<=32;i++){const t=.5+i/32*Math.PI*1.6;points.push(new THREE.Vector3(Math.cos(t)*.15,0,Math.sin(t)*.21));}points.push(new THREE.Vector3(-.01,0,.11),new THREE.Vector3(.07,0,.01),new THREE.Vector3(0,0,-.06));}if(sense===2){points.push(new THREE.Vector3(-.04,0,-.21),new THREE.Vector3(-.17,0,.12),new THREE.Vector3(-.1,0,.2),new THREE.Vector3(0,0,.13),new THREE.Vector3(.1,0,.2),new THREE.Vector3(.17,0,.12),new THREE.Vector3(.04,0,-.21));}if(sense===3){for(let i=0;i<=30;i++){const t=i/30*Math.PI*2;points.push(new THREE.Vector3(Math.cos(t)*.22,0,Math.sin(t)*.12));}points.push(new THREE.Vector3(0,0,0),new THREE.Vector3(.07,0,.07),new THREE.Vector3(.07,0,.24),new THREE.Vector3(-.07,0,.24),new THREE.Vector3(-.07,0,.07));}if(sense===4){points.push(...[[-.2,.04],[-.24,-.08],[-.18,-.12],[-.1,-.01],[-.12,-.23],[-.06,-.25],[-.03,-.06],[0,-.28],[.06,-.28],[.07,-.06],[.11,-.23],[.17,-.21],[.14,.01],[.2,-.1],[.25,-.06],[.18,.2],[.06,.25],[-.08,.23],[-.2,.04]].map(([a,b])=>new THREE.Vector3(a,0,b)));}const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),material);line.position.set(x,y,z);parent.add(line);}
export function createBoard({labels=true}={}){const group=new THREE.Group();group.name='5 Senses — complete tabletop';const baseMat=mat('#273340',.78,.13),edgeMat=mat('#394855',.65,.2);const base=mesh(roundedBox(6.65,.22,6.65,.35),baseMat,group,0,-.16,0);base.name='Rounded tabletop base';mesh(roundedBox(6.72,.07,6.72,.37),edgeMat,group,0,-.18,0);mesh(roundedBox(6.4,.025,6.4,.3),mat('#202c37'),group,0,.06,0);
// An unbroken dotted light trail makes the spiral unambiguous.
const connectors=[];for(let i=0;i<PATH.length-1;i++){const a=pointAt(i),b=pointAt(i+1),dx=b.x-a.x,dz=b.z-a.z;const geo=new THREE.ConeGeometry(.046,.12,3);geo.rotateX(Math.PI/2);const arrow=mesh(geo,mat('#95aa9f',.7),group,(a.x+b.x)/2,.205,(a.z+b.z)/2);arrow.rotation.y=Math.atan2(dx,dz);connectors.push(arrow);}
const tiles=[],beacons=[];PATH.forEach(([gx,gz],i)=>{const x=gx*STEP,z=gz*STEP,gi=GATES.indexOf(i),s=(i-1+5)%5;let tint=i===0?'#94b591':i===24?'#bfaa81':gi>=0?SENSES[gi].color:'#3a4957';const border=mat(tint,.7,.05);const rim=mesh(roundedBox(1.015,.07,1.015,.14),border,group,x,.09,z);rim.name=`Space ${i}${gi>=0?' — '+SENSES[gi].name+' beacon':''}`;const tile=mesh(roundedBox(.955,.09,.955,.11),mat(i===0?'#48624d':i===24?'#746349':gi>=0?'#4d4b60':'#303f4e',.85),group,x,.15,z);tiles.push(tile);
if(gi>=0){const ring=mesh(new THREE.TorusGeometry(.34,.016,6,48),mat(tint),group,x,.255,z);ring.rotation.x=Math.PI/2;icon(group,gi,tint,x,.26,z-.05);const stem=mesh(new THREE.CylinderGeometry(.03,.05,.2,10),mat(tint,.4,.2),group,x-.36,.35,z-.35);const orbMat=new THREE.MeshStandardMaterial({color:tint,emissive:tint,emissiveIntensity:.05,roughness:.4});const orb=mesh(new THREE.SphereGeometry(.07,16,12),orbMat,group,x-.36,.49,z-.35);beacons.push({orb,ring,stem,tint});if(labels)label(group,String(i),SENSES[gi].name.toUpperCase(),tint,x,.265,z+.22,.6);}else if(i===0){if(labels)label(group,'↗','START','#cfdfba',x,.255,z,.8);}else if(i===24){const ring=mesh(new THREE.TorusGeometry(.36,.02,8,48),mat('#c9b68c'),group,x,.26,z);ring.rotation.x=Math.PI/2;if(labels)label(group,'◎','CORE','#e4d1a7',x,.265,z,.65);}else{if(labels)label(group,String(i),SENSES[s].verb.toUpperCase(),'#9caebc',x,.255,z,.65);const pip=mesh(new THREE.CylinderGeometry(.027,.027,.008,10),mat(SENSES[s].color),group,x-.35,.254,z-.35);}});
const blu=makeCharacter('#79b9ce',.78),ember=makeCharacter('#e89278',.78);group.add(blu,ember);const guardian=makeCharacter('#8f9684',.55,true);guardian.position.set(0,.23,0);guardian.rotation.y=.2;group.add(guardian);const players=[blu,ember];players.forEach((p,i)=>{const v=pointAt(0);p.position.set(v.x+(i===0?-.23:.23),.25,v.z);});
// Small brass feet and etched corner pips finish the physical object.
for(const x of [-2.85,2.85])for(const z of [-2.85,2.85]){mesh(new THREE.CylinderGeometry(.12,.1,.13,16),mat('#8f987c',.5,.25),group,x,-.22,z);mesh(new THREE.CylinderGeometry(.025,.025,.008,12),mat('#94a492'),group,x,.09,z);}
if(!labels)PATH.forEach(([gx,gz],i)=>{if(i!==24)geometricNumber(group,i,GATES.includes(i)?SENSES[GATES.indexOf(i)].color:'#a6b8c6',gx*STEP,.262,gz*STEP+(GATES.includes(i)?.28:0));});
return {group,players,tiles,beacons,guardian,connectors};}
